BEGIN;
CREATE TABLE "FinanceCashFlowReview"(id UUID PRIMARY KEY,"journalId" UUID NOT NULL REFERENCES "FinanceJournalEntry" ON DELETE RESTRICT,"replacesId" UUID UNIQUE REFERENCES "FinanceCashFlowReview" ON DELETE RESTRICT,evidence TEXT NOT NULL CHECK(length(trim(evidence)) BETWEEN 3 AND 1000),reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 3 AND 500),"sourceHash" TEXT NOT NULL CHECK("sourceHash"~'^[0-9a-f]{64}$'),"sourceSnapshot" JSONB NOT NULL,state TEXT NOT NULL DEFAULT 'DRAFT' CHECK(state IN('DRAFT','CONFIRMED','SUPERSEDED')),version INTEGER NOT NULL DEFAULT 1,"createdById" UUID NOT NULL REFERENCES "Person" ON DELETE RESTRICT,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"supersededById" UUID REFERENCES "Person" ON DELETE RESTRICT,"supersededAt" TIMESTAMPTZ,"supersedeReason" TEXT,CHECK((state='DRAFT' AND version=1 OR state='CONFIRMED' AND version=2) AND "supersededById" IS NULL AND "supersededAt" IS NULL AND "supersedeReason" IS NULL OR state='SUPERSEDED' AND version=3 AND "supersededById" IS NOT NULL AND "supersededAt" IS NOT NULL AND length(trim("supersedeReason")) BETWEEN 3 AND 500));
CREATE UNIQUE INDEX "FinanceCashFlowReview_one_current" ON "FinanceCashFlowReview"("journalId") WHERE state='CONFIRMED';
CREATE INDEX "FinanceCashFlowReview_journalId_state_id_idx" ON "FinanceCashFlowReview"("journalId",state,id);
CREATE TABLE "FinanceCashFlowComponent"(id UUID PRIMARY KEY,"reviewId" UUID NOT NULL REFERENCES "FinanceCashFlowReview" ON DELETE RESTRICT,"journalLineId" UUID NOT NULL REFERENCES "FinanceJournalLine" ON DELETE RESTRICT,category TEXT NOT NULL CHECK(category IN('OPERATING','INVESTING','FINANCING','INTERNAL')),amount NUMERIC(20,2) NOT NULL CHECK(amount>0),UNIQUE("reviewId","journalLineId",category));
CREATE INDEX "FinanceCashFlowComponent_journalLineId_reviewId_idx" ON "FinanceCashFlowComponent"("journalLineId","reviewId");
CREATE TRIGGER "FinanceCashFlowReview_lock" BEFORE INSERT OR UPDATE OR DELETE ON "FinanceCashFlowReview" FOR EACH STATEMENT EXECUTE FUNCTION encova_finance_config_lock();
CREATE TRIGGER "FinanceCashFlowComponent_lock" BEFORE INSERT OR UPDATE OR DELETE ON "FinanceCashFlowComponent" FOR EACH STATEMENT EXECUTE FUNCTION encova_finance_config_lock();
-- A typed opposite is linked by its actual original entry, never by equal date/amount.
CREATE FUNCTION encova_finance_cash_flow_original(entry_id UUID) RETURNS UUID LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT coalesce(e."reversalOfId",om.id,oc.id,os.id,oa.id) FROM public."FinanceJournalEntry" e
 LEFT JOIN public."FinanceMovement" m ON m.id=e."movementId" LEFT JOIN public."FinanceJournalEntry" om ON om."movementId"=m."reversalOfId"
 LEFT JOIN public."FinanceCustomerDocument" c ON c.id=e."customerDocumentId" LEFT JOIN public."FinanceJournalEntry" oc ON oc."customerDocumentId"=c."reversalOfId"
 LEFT JOIN public."FinanceSupplierDocument" s ON s.id=e."supplierDocumentId" LEFT JOIN public."FinanceJournalEntry" os ON os."supplierDocumentId"=s."reversalOfId"
 LEFT JOIN public."FinanceAssetMovement" a ON a.id=e."assetMovementId" LEFT JOIN public."FinanceJournalEntry" oa ON oa."assetMovementId"=a."reversalOfId" WHERE e.id=entry_id
$$;
CREATE FUNCTION encova_finance_cash_flow_source(entry_id UUID) RETURNS JSONB LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('journalId',e.id,'postingDate',e."postingDate",'sourceType',e."sourceType",'sourceId',e."sourceId",'sourceAction',e."sourceAction",'reference',e.reference,'description',e.description,'lines',coalesce((SELECT jsonb_agg(jsonb_build_object('id',l.id,'sequence',l.sequence,'accountId',l."accountId",'code',a.code,'debit',l.debit::text,'credit',l.credit::text) ORDER BY l.sequence,l.id) FROM public."FinanceJournalLine" l JOIN public."FinanceAccount" a ON a.id=l."accountId" WHERE l."journalId"=e.id AND a."controlType"='CASH' AND a.currency='PKR'),'[]'::jsonb)) FROM public."FinanceJournalEntry" e WHERE e.id=entry_id
$$;
CREATE FUNCTION encova_finance_cash_flow_basis(entry_id UUID) RETURNS TEXT LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT encode(sha256(convert_to(jsonb_build_object('source',public.encova_finance_cash_flow_source(entry_id),'review',(SELECT jsonb_build_object('id',r.id,'version',r.version) FROM public."FinanceCashFlowReview" r WHERE r."journalId"=entry_id AND r.state='CONFIRMED'),'reversals',coalesce((SELECT jsonb_agg(jsonb_build_object('id',e.id,'date',e."postingDate") ORDER BY e.id) FROM public."FinanceJournalEntry" e WHERE public.encova_finance_cash_flow_original(e.id)=entry_id),'[]'::jsonb))::text,'UTF8')),'hex')
$$;
CREATE FUNCTION encova_finance_cash_flow_validate(review_id UUID) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE r public."FinanceCashFlowReview"%ROWTYPE;source JSONB;BEGIN
 SELECT * INTO r FROM public."FinanceCashFlowReview" WHERE id=review_id;
 IF r.id IS NULL OR r.state='DRAFT' THEN RAISE EXCEPTION 'FINANCE_CASH_FLOW_INCOMPLETE' USING ERRCODE='P0001';END IF;
 source:=public.encova_finance_cash_flow_source(r."journalId");
 IF public.encova_finance_cash_flow_original(r."journalId") IS NOT NULL OR source->>'sourceType' IN('OPENING','YEAR_CLOSE') THEN RAISE EXCEPTION 'FINANCE_CASH_FLOW_DERIVED' USING ERRCODE='P0001';END IF;
 IF jsonb_array_length(source->'lines') NOT BETWEEN 1 AND 200 OR (SELECT count(*) FROM public."FinanceCashFlowComponent" WHERE "reviewId"=r.id) NOT BETWEEN 1 AND 800 OR r."sourceHash"<>encode(sha256(convert_to(source::text,'UTF8')),'hex') OR r."sourceSnapshot"->'source' IS DISTINCT FROM source THEN RAISE EXCEPTION 'FINANCE_CASH_FLOW_INCOMPLETE' USING ERRCODE='P0001';END IF;
 IF EXISTS(SELECT 1 FROM public."FinanceCashFlowComponent" c LEFT JOIN public."FinanceJournalLine" l ON l.id=c."journalLineId" LEFT JOIN public."FinanceAccount" a ON a.id=l."accountId" WHERE c."reviewId"=r.id AND(l."journalId" IS DISTINCT FROM r."journalId" OR a."controlType" IS DISTINCT FROM 'CASH' OR a.currency IS DISTINCT FROM 'PKR')) OR EXISTS(SELECT 1 FROM public."FinanceJournalLine" l JOIN public."FinanceAccount" a ON a.id=l."accountId" WHERE l."journalId"=r."journalId" AND a."controlType"='CASH' AND a.currency='PKR' AND abs(l.debit-l.credit) IS DISTINCT FROM(SELECT sum(c.amount) FROM public."FinanceCashFlowComponent" c WHERE c."reviewId"=r.id AND c."journalLineId"=l.id)) THEN RAISE EXCEPTION 'FINANCE_CASH_FLOW_TOTAL' USING ERRCODE='P0001';END IF;
 IF coalesce((SELECT sum(sign(l.debit-l.credit)*c.amount) FROM public."FinanceCashFlowComponent" c JOIN public."FinanceJournalLine" l ON l.id=c."journalLineId" WHERE c."reviewId"=r.id AND c.category='INTERNAL'),0)<>0 THEN RAISE EXCEPTION 'FINANCE_CASH_FLOW_INTERNAL' USING ERRCODE='P0001';END IF;
 IF NOT EXISTS(SELECT 1 FROM public."FinanceJournalLine" l JOIN public."FinanceAccount" a ON a.id=l."accountId" WHERE l."journalId"=r."journalId" AND a."controlType"<>'CASH') AND EXISTS(SELECT 1 FROM public."FinanceCashFlowComponent" WHERE "reviewId"=r.id AND category<>'INTERNAL') THEN RAISE EXCEPTION 'FINANCE_CASH_FLOW_INTERNAL' USING ERRCODE='P0001';END IF;
 IF r."sourceSnapshot"->'components' IS DISTINCT FROM(SELECT jsonb_agg(jsonb_build_object('journalLineId',c."journalLineId",'category',c.category,'amount',c.amount::text) ORDER BY c."journalLineId",c.category) FROM public."FinanceCashFlowComponent" c WHERE c."reviewId"=r.id) THEN RAISE EXCEPTION 'FINANCE_CASH_FLOW_INCOMPLETE' USING ERRCODE='P0001';END IF;
 IF r."replacesId" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."FinanceCashFlowReview" p WHERE p.id=r."replacesId" AND p."journalId"=r."journalId" AND p.state='SUPERSEDED') THEN RAISE EXCEPTION 'FINANCE_STALE_VERSION' USING ERRCODE='P0001';END IF;
END $$;
CREATE FUNCTION encova_finance_cash_flow_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'FINANCE_CASH_FLOW_RETAINED' USING ERRCODE='P0001';END IF;
 IF TG_TABLE_NAME='FinanceCashFlowComponent' THEN
  IF TG_OP<>'INSERT' OR NOT EXISTS(SELECT 1 FROM public."FinanceCashFlowReview" WHERE id=NEW."reviewId" AND state='DRAFT') THEN RAISE EXCEPTION 'FINANCE_CASH_FLOW_RETAINED' USING ERRCODE='P0001';END IF;
 ELSIF TG_OP='INSERT' THEN
  IF NEW.state<>'DRAFT' OR NEW.version<>1 THEN RAISE EXCEPTION 'FINANCE_CASH_FLOW_INCOMPLETE' USING ERRCODE='P0001';END IF;
 ELSE
  IF (to_jsonb(NEW)-ARRAY['state','version','supersededById','supersededAt','supersedeReason']) IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['state','version','supersededById','supersededAt','supersedeReason']) OR NOT(OLD.state='DRAFT' AND NEW.state='CONFIRMED' AND NEW.version=2 OR OLD.state='CONFIRMED' AND NEW.state='SUPERSEDED' AND NEW.version=3) THEN RAISE EXCEPTION 'FINANCE_CASH_FLOW_RETAINED' USING ERRCODE='P0001';END IF;
 END IF;RETURN NEW;
END $$;
CREATE FUNCTION encova_finance_cash_flow_deferred() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN
 IF TG_TABLE_NAME='FinanceCashFlowReview' THEN PERFORM public.encova_finance_cash_flow_validate(NEW.id);ELSE PERFORM public.encova_finance_cash_flow_validate(NEW."reviewId");END IF;RETURN NULL;
END $$;
CREATE TRIGGER "FinanceCashFlowReview_guard" BEFORE INSERT OR UPDATE OR DELETE ON "FinanceCashFlowReview" FOR EACH ROW EXECUTE FUNCTION encova_finance_cash_flow_guard();
CREATE TRIGGER "FinanceCashFlowComponent_guard" BEFORE INSERT OR UPDATE OR DELETE ON "FinanceCashFlowComponent" FOR EACH ROW EXECUTE FUNCTION encova_finance_cash_flow_guard();
CREATE CONSTRAINT TRIGGER "FinanceCashFlowReview_complete" AFTER INSERT OR UPDATE ON "FinanceCashFlowReview" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION encova_finance_cash_flow_deferred();
CREATE CONSTRAINT TRIGGER "FinanceCashFlowComponent_complete" AFTER INSERT ON "FinanceCashFlowComponent" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION encova_finance_cash_flow_deferred();
CREATE FUNCTION encova_finance_cash_flow_command(actor UUID,provider TEXT,session_id TEXT,verified_at TIMESTAMPTZ,action TEXT,input JSONB,request_key TEXT,request_id UUID) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE r public."FinanceCashFlowReview"%ROWTYPE;old_review public."FinanceCashFlowReview"%ROWTYPE;receipt public."FinanceLedgerReceipt"%ROWTYPE;source JSONB;parts JSONB;digest TEXT;result JSONB;entry_id UUID;why TEXT;BEGIN
 IF action IS DISTINCT FROM 'CONFIRM' OR jsonb_typeof(input) IS DISTINCT FROM 'object' OR input-ARRAY['journalId','basisHash','expectedReviewId','expectedVersion','components','evidence','reason']<>'{}'::jsonb OR request_key IS NULL OR length(request_key) NOT BETWEEN 8 AND 128 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 IF verified_at IS NULL OR verified_at<CURRENT_TIMESTAMP-interval '5 minutes' OR verified_at>CURRENT_TIMESTAMP+interval '5 seconds' THEN RAISE EXCEPTION 'FINANCE_REAUTH_REQUIRED' USING ERRCODE='P0001';END IF;
 IF jsonb_typeof(input->'journalId') IS DISTINCT FROM 'string' OR jsonb_typeof(input->'basisHash') IS DISTINCT FROM 'string' OR input->>'basisHash'!~'^[0-9a-f]{64}$' OR jsonb_typeof(input->'evidence') IS DISTINCT FROM 'string' OR length(trim(input->>'evidence')) NOT BETWEEN 3 AND 1000 OR jsonb_typeof(input->'reason') IS DISTINCT FROM 'string' OR length(trim(input->>'reason')) NOT BETWEEN 3 AND 500 OR jsonb_typeof(input->'components') IS DISTINCT FROM 'array' OR jsonb_array_length(input->'components') NOT BETWEEN 1 AND 800 OR(input->>'expectedVersion' IS NOT NULL AND (jsonb_typeof(input->'expectedVersion') IS DISTINCT FROM 'number' OR (input->>'expectedVersion')::integer<>2)) THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(input->'components') c WHERE jsonb_typeof(c) IS DISTINCT FROM 'object' OR c-ARRAY['journalLineId','category','amount']<>'{}'::jsonb OR jsonb_typeof(c->'journalLineId') IS DISTINCT FROM 'string' OR jsonb_typeof(c->'category') IS DISTINCT FROM 'string' OR c->>'category' NOT IN('OPERATING','INVESTING','FINANCING','INTERNAL') OR jsonb_typeof(c->'amount') IS DISTINCT FROM 'string' OR c->>'amount'!~'^(0|[1-9][0-9]{0,17})\.[0-9]{2}$' OR (c->>'amount')::numeric<=0) THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 PERFORM pg_advisory_xact_lock(987661);PERFORM public.encova_finance_lock_person(actor);
 IF NOT EXISTS(SELECT 1 FROM public."Person" WHERE id=actor AND role='SUPER_ADMIN' AND status='ACTIVE') OR NOT public.encova_finance_session_ok(actor,provider,session_id) OR NOT EXISTS(SELECT 1 FROM public."FinanceGrant" WHERE "userId"=actor AND "revokedAt" IS NULL) THEN RAISE EXCEPTION 'FINANCE_FORBIDDEN' USING ERRCODE='P0001';END IF;
 PERFORM pg_advisory_xact_lock(629815);
 digest:=encode(sha256(convert_to(input::text,'UTF8')),'hex');SELECT * INTO receipt FROM public."FinanceLedgerReceipt" WHERE "actorId"=actor AND operation='CASH_FLOW_CONFIRM' AND key=request_key;
 IF receipt.id IS NOT NULL THEN IF receipt."requestHash"<>digest THEN RAISE EXCEPTION 'FINANCE_IDEMPOTENCY_CONFLICT' USING ERRCODE='P0001';END IF;RETURN receipt.result;END IF;
 entry_id:=(input->>'journalId')::uuid;source:=public.encova_finance_cash_flow_source(entry_id);
 IF source IS NULL THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 IF public.encova_finance_cash_flow_original(entry_id) IS NOT NULL OR source->>'sourceType' IN('OPENING','YEAR_CLOSE') THEN RAISE EXCEPTION 'FINANCE_CASH_FLOW_DERIVED' USING ERRCODE='P0001';END IF;
 SELECT * INTO old_review FROM public."FinanceCashFlowReview" WHERE "journalId"=entry_id AND state='CONFIRMED' FOR UPDATE;
 IF old_review.id IS DISTINCT FROM (input->>'expectedReviewId')::uuid OR old_review.version IS DISTINCT FROM(input->>'expectedVersion')::integer OR public.encova_finance_cash_flow_basis(entry_id) IS DISTINCT FROM input->>'basisHash' THEN RAISE EXCEPTION 'FINANCE_STALE_VERSION' USING ERRCODE='P0001';END IF;
 IF EXISTS(SELECT 1 FROM public."FinanceJournalEntry" e LEFT JOIN public."FinancePeriod" p ON p.id=e."periodId" WHERE(e.id=entry_id OR public.encova_finance_cash_flow_original(e.id)=entry_id) AND p.state IS DISTINCT FROM 'OPEN') THEN RAISE EXCEPTION 'FINANCE_PERIOD_CLOSED' USING ERRCODE='P0001';END IF;
 SELECT jsonb_agg(jsonb_build_object('journalLineId',(c->>'journalLineId')::uuid,'category',c->>'category','amount',((c->>'amount')::numeric(20,2))::text) ORDER BY (c->>'journalLineId')::uuid,c->>'category') INTO parts FROM jsonb_array_elements(input->'components') c;
 why:=trim(input->>'reason');
 IF old_review.id IS NOT NULL THEN UPDATE public."FinanceCashFlowReview" SET state='SUPERSEDED',version=3,"supersededById"=actor,"supersededAt"=CURRENT_TIMESTAMP,"supersedeReason"=why WHERE id=old_review.id;END IF;
 INSERT INTO public."FinanceCashFlowReview"(id,"journalId","replacesId",evidence,reason,"sourceHash","sourceSnapshot","createdById") VALUES(gen_random_uuid(),entry_id,old_review.id,trim(input->>'evidence'),why,encode(sha256(convert_to(source::text,'UTF8')),'hex'),jsonb_build_object('source',source,'components',parts),actor) RETURNING * INTO r;
 INSERT INTO public."FinanceCashFlowComponent"(id,"reviewId","journalLineId",category,amount) SELECT gen_random_uuid(),r.id,(c->>'journalLineId')::uuid,c->>'category',(c->>'amount')::numeric FROM jsonb_array_elements(parts)c;
 UPDATE public."FinanceCashFlowReview" SET state='CONFIRMED',version=2 WHERE id=r.id RETURNING * INTO r;
 PERFORM public.encova_finance_cash_flow_validate(r.id);
 result:=jsonb_build_object('id',r.id,'journalId',r."journalId",'version',r.version,'state',r.state);
 INSERT INTO public."FinanceLedgerReceipt"(id,"actorId",operation,key,"requestHash",result) VALUES(gen_random_uuid(),actor,'CASH_FLOW_CONFIRM',request_key,digest,result);
 INSERT INTO public."FinanceAuditEvent"(id,"actorId",action,"entityType","entityId",reason,data,"requestId") VALUES(gen_random_uuid(),actor,'FINANCE_CASH_FLOW_CONFIRM','FinanceCashFlowReview',r.id,why,jsonb_build_object('before',CASE WHEN old_review.id IS NOT NULL THEN to_jsonb(old_review) ELSE NULL END,'after',to_jsonb(r),'nonpostingComponentsOnly',true),request_id);RETURN result;
 EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'FINANCE_DUPLICATE' USING ERRCODE='P0001';WHEN data_exception OR check_violation OR not_null_violation OR foreign_key_violation THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END $$;
-- Exact posted cash legs and retained reviewed components; reversals inherit an opposite on the same actual account and sequence.
CREATE FUNCTION encova_finance_cash_flow_lines(cutoff DATE) RETURNS TABLE("journalId" UUID,"postingDate" DATE,reference TEXT,"sourceType" TEXT,"sourceId" UUID,"journalLineId" UUID,"accountId" UUID,code TEXT,"accountName" TEXT,sequence INTEGER,delta NUMERIC,"originalJournalId" UUID,"reviewId" UUID,"reviewVersion" INTEGER,classified BOOLEAN,components JSONB) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 WITH entries AS MATERIALIZED(SELECT e.*,public.encova_finance_cash_flow_original(e.id) AS original FROM public."FinanceJournalEntry" e WHERE e."postingDate"<=cutoff),
 legs AS(SELECT e.id AS jid,e."postingDate",e.reference,e."sourceType",e."sourceId",l.id AS lid,l."accountId",a.code,a.name,l.sequence,l.debit-l.credit AS delta,e.original,r.id AS rid,r.version,CASE WHEN e.original IS NULL THEN l.id WHEN ol.debit=l.credit AND ol.credit=l.debit THEN ol.id ELSE NULL END AS mapped_line FROM entries e JOIN public."FinanceJournalLine" l ON l."journalId"=e.id JOIN public."FinanceAccount" a ON a.id=l."accountId" AND a."controlType"='CASH' AND a.currency='PKR' LEFT JOIN public."FinanceJournalLine" ol ON ol."journalId"=e.original AND ol."accountId"=l."accountId" AND ol.sequence=l.sequence LEFT JOIN public."FinanceCashFlowReview" r ON r."journalId"=coalesce(e.original,e.id) AND r.state='CONFIRMED')
 SELECT b.jid,b."postingDate",b.reference,b."sourceType",b."sourceId",b.lid,b."accountId",b.code,b.name,b.sequence,b.delta,b.original,b.rid,b.version,b.rid IS NOT NULL AND abs(b.delta)=coalesce(c.amount,0),coalesce(c.parts,'[]'::jsonb) FROM legs b LEFT JOIN LATERAL(SELECT sum(c.amount) AS amount,jsonb_agg(jsonb_build_object('category',c.category,'amount',c.amount::text,'signedAmount',(sign(b.delta)*c.amount)::numeric(20,2)::text) ORDER BY c.category) AS parts FROM public."FinanceCashFlowComponent" c WHERE c."reviewId"=b.rid AND c."journalLineId"=b.mapped_line)c ON true
$$;
CREATE FUNCTION encova_finance_cash_flow_report(date_from DATE,cutoff DATE,search TEXT,requested_page INTEGER) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE result JSONB;BEGIN
 WITH actual AS MATERIALIZED(SELECT * FROM public.encova_finance_cash_flow_lines(cutoff)),period AS MATERIALIZED(SELECT * FROM actual WHERE "postingDate">=date_from),
 balances AS(SELECT coalesce(sum(delta) FILTER(WHERE "postingDate"<date_from),0) AS opening,coalesce(sum(delta),0) AS closing FROM actual),
 categories AS(SELECT p->>'category' AS category,sum((p->>'signedAmount')::numeric) FILTER(WHERE(p->>'signedAmount')::numeric>0) AS inflows,-sum((p->>'signedAmount')::numeric) FILTER(WHERE(p->>'signedAmount')::numeric<0) AS outflows,sum((p->>'signedAmount')::numeric) AS net FROM period b CROSS JOIN LATERAL jsonb_array_elements(b.components)p WHERE b.classified GROUP BY p->>'category'),
 summary AS(SELECT count(DISTINCT "journalId") FILTER(WHERE NOT classified)::integer AS missing,coalesce(sum(delta) FILTER(WHERE NOT classified),0) AS unclassified,encode(sha256(convert_to(coalesce(jsonb_agg(jsonb_build_object('line',"journalLineId",'review',"reviewId",'version',"reviewVersion",'classified',classified) ORDER BY "journalLineId"),'[]'::jsonb)::text,'UTF8')),'hex') AS digest FROM period),
 groups AS(SELECT "journalId",min("postingDate") AS "postingDate",min(reference) AS reference,min("sourceType") AS "sourceType",min("sourceId"::text)::uuid AS "sourceId",min("originalJournalId"::text)::uuid AS "originalJournalId",min("reviewId"::text)::uuid AS "reviewId",bool_and(classified) AS classified,sum(delta) AS "cashChange",count(*)::integer AS "cashLegCount" FROM period GROUP BY "journalId"),
 displayed AS MATERIALIZED(SELECT * FROM groups WHERE concat_ws(' ',reference,"sourceType","journalId") ILIKE '%'||search||'%'),counts AS(SELECT count(*)::integer AS total,greatest(1,ceil(count(*)/25.0)::integer) AS pages FROM displayed),paging AS(SELECT *,least(requested_page,pages) AS page FROM counts),bounded AS(SELECT * FROM displayed ORDER BY "postingDate","journalId" LIMIT 25 OFFSET((SELECT page FROM paging)-1)*25),rows AS(SELECT coalesce(jsonb_agg((to_jsonb(b)-'cashChange')||jsonb_build_object('cashChange',round(b."cashChange",2)::text) ORDER BY b."postingDate",b."journalId"),'[]'::jsonb) AS items FROM bounded b),external AS(SELECT coalesce(sum(net) FILTER(WHERE category<>'INTERNAL'),0) AS net,coalesce(sum(net) FILTER(WHERE category='INTERNAL'),0) AS internal FROM categories)
 SELECT jsonb_build_object('metadata',public.encova_finance_report_metadata(date_from,cutoff,jsonb_build_object('report','CASH_FLOW','cashScope','All PKR CASH controls, including archived accounts and designated cash equivalents','componentDigest',s.digest,'displaySearch',search)),'openingBalance',round(b.opening,2)::text,'closingBalance',round(b.closing,2)::text,'externalNet',round(x.net,2)::text,'internalNet',round(x.internal,2)::text,'unclassifiedNet',round(s.unclassified,2)::text,'difference',round(b.closing-b.opening-x.net,2)::text,'unclassifiedCount',s.missing,'classificationReady',s.missing=0 AND b.closing-b.opening=x.net AND x.internal=0,'categories',(SELECT jsonb_agg(jsonb_build_object('category',k,'inflows',round(coalesce(c.inflows,0),2)::text,'outflows',round(coalesce(c.outflows,0),2)::text,'net',round(coalesce(c.net,0),2)::text) ORDER BY k) FROM unnest(ARRAY['OPERATING','INVESTING','FINANCING'])k LEFT JOIN categories c ON c.category=k),'items',rows.items,'total',paging.total,'page',paging.page,'pages',paging.pages) INTO result FROM balances b CROSS JOIN summary s CROSS JOIN external x CROSS JOIN paging CROSS JOIN rows;RETURN result;
END $$;
CREATE FUNCTION encova_finance_cash_flow_read(actor UUID,kind TEXT,input JSONB) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE source JSONB;r public."FinanceCashFlowReview"%ROWTYPE;entry_id UUID;original UUID;history JSONB;lines JSONB;date_from DATE;cutoff DATE;requested_page INTEGER;BEGIN
 IF NOT EXISTS(SELECT 1 FROM public."Person" WHERE id=actor AND role='SUPER_ADMIN' AND status='ACTIVE') OR NOT EXISTS(SELECT 1 FROM public."FinanceGrant" WHERE "userId"=actor AND "revokedAt" IS NULL) THEN RAISE EXCEPTION 'FINANCE_FORBIDDEN' USING ERRCODE='P0001';END IF;
 IF jsonb_typeof(input) IS DISTINCT FROM 'object' OR kind IS NULL OR kind NOT IN('REPORT','REVIEW') THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 IF kind='REPORT' THEN
  IF input-ARRAY['from','to','page','q']<>'{}'::jsonb OR EXISTS(SELECT 1 FROM unnest(ARRAY['from','to','q'])k WHERE jsonb_typeof(input->k) IS DISTINCT FROM 'string') OR input->>'from'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR input->>'to'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR length(input->>'q')>100 OR jsonb_typeof(input->'page') IS DISTINCT FROM 'number' OR (input->>'page')::integer NOT BETWEEN 1 AND 10000 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  date_from:=(input->>'from')::date;cutoff:=(input->>'to')::date;IF date_from<DATE '0001-01-01' OR cutoff>DATE '9999-12-31' OR date_from>cutoff THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  RETURN public.encova_finance_cash_flow_report(date_from,cutoff,input->>'q',(input->>'page')::integer);
 END IF;
 IF input-ARRAY['journalId','page']<>'{}'::jsonb OR jsonb_typeof(input->'journalId') IS DISTINCT FROM 'string' OR jsonb_typeof(input->'page') IS DISTINCT FROM 'number' OR (input->>'page')::integer NOT BETWEEN 1 AND 10000 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 entry_id:=(input->>'journalId')::uuid;source:=public.encova_finance_cash_flow_source(entry_id);IF source IS NULL OR jsonb_array_length(source->'lines') NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 original:=public.encova_finance_cash_flow_original(entry_id);SELECT * INTO r FROM public."FinanceCashFlowReview" WHERE "journalId"=coalesce(original,entry_id) AND state='CONFIRMED';
 SELECT coalesce(jsonb_agg(to_jsonb(b) ORDER BY b."createdAt" DESC,b.id),'[]'::jsonb) INTO history FROM(SELECT id,state,version,evidence,reason,"createdAt","createdById","supersededAt","supersededById","supersedeReason","replacesId","sourceHash" FROM public."FinanceCashFlowReview" WHERE "journalId"=coalesce(original,entry_id) ORDER BY "createdAt" DESC,id LIMIT 25 OFFSET((input->>'page')::integer-1)*25)b;
 SELECT jsonb_agg(jsonb_build_object('id',l.id,'sequence',l.sequence,'accountId',a.id,'code',a.code,'name',a.name,'active',a.active,'amount',abs(l.debit-l.credit)::numeric(20,2)::text,'direction',CASE WHEN l.debit>0 THEN 'INFLOW' ELSE 'OUTFLOW' END,'components',coalesce((SELECT jsonb_agg(jsonb_build_object('category',c.category,'amount',c.amount::text) ORDER BY c.category) FROM public."FinanceCashFlowComponent" c WHERE c."reviewId"=r.id AND c."journalLineId"=coalesce(ol.id,l.id)),'[]'::jsonb)) ORDER BY l.sequence,l.id) INTO lines FROM public."FinanceJournalLine" l JOIN public."FinanceAccount" a ON a.id=l."accountId" LEFT JOIN public."FinanceJournalLine" ol ON ol."journalId"=original AND ol."accountId"=l."accountId" AND ol.sequence=l.sequence AND ol.debit=l.credit AND ol.credit=l.debit WHERE l."journalId"=entry_id AND a."controlType"='CASH' AND a.currency='PKR';
 RETURN jsonb_build_object('source',source-'lines','lines',lines,'originalJournalId',original,'basisHash',public.encova_finance_cash_flow_basis(entry_id),'review',CASE WHEN r.id IS NOT NULL THEN jsonb_build_object('id',r.id,'version',r.version,'evidence',r.evidence,'reason',r.reason,'createdAt',r."createdAt",'sourceHash',r."sourceHash") ELSE NULL END,'reviewAllowed',original IS NULL AND source->>'sourceType' NOT IN('OPENING','YEAR_CLOSE') AND NOT EXISTS(SELECT 1 FROM public."FinanceJournalEntry" e JOIN public."FinancePeriod" p ON p.id=e."periodId" WHERE(e.id=entry_id OR public.encova_finance_cash_flow_original(e.id)=entry_id) AND p.state<>'OPEN'),'internalOnly',NOT EXISTS(SELECT 1 FROM public."FinanceJournalLine" l JOIN public."FinanceAccount" a ON a.id=l."accountId" WHERE l."journalId"=entry_id AND a."controlType"<>'CASH'),'history',history,'page',(input->>'page')::integer,'total',(SELECT count(*) FROM public."FinanceCashFlowReview" WHERE "journalId"=coalesce(original,entry_id)));
 EXCEPTION WHEN data_exception THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END $$;
DO $$ DECLARE t TEXT;f RECORD;r TEXT;BEGIN
 FOREACH t IN ARRAY ARRAY['FinanceCashFlowReview','FinanceCashFlowComponent'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC',t);
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='encova_app') THEN EXECUTE format('GRANT SELECT ON public.%I TO encova_app',t);EXECUTE format('CREATE POLICY encova_server_read ON public.%I FOR SELECT TO encova_app USING(true)',t);END IF;
 FOREACH r IN ARRAY ARRAY['anon','authenticated'] LOOP IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r) THEN EXECUTE format('REVOKE ALL ON public.%I FROM %I',t,r);END IF;END LOOP;END LOOP;
 FOR f IN SELECT oid::regprocedure AS signature FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname LIKE 'encova_finance_cash_flow_%' LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);FOREACH r IN ARRAY ARRAY['encova_app','anon','authenticated'] LOOP IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r) THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r);END IF;END LOOP;END LOOP;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='encova_app') THEN GRANT EXECUTE ON FUNCTION public.encova_finance_cash_flow_command(UUID,TEXT,TEXT,TIMESTAMPTZ,TEXT,JSONB,TEXT,UUID),public.encova_finance_cash_flow_read(UUID,TEXT,JSONB) TO encova_app;END IF;
END $$;
COMMIT;
